import{_ as t,o as a,c as r,a2 as s}from"./chunks/framework.B8TleWq7.js";const u=JSON.parse('{"title":"Keel","description":"","frontmatter":{"layout":"home","title":"Keel","hero":{"name":"Keel","text":"A shared framework for Roblox games","tagline":"Loading, saving, networking, game data, UI and purchases, written once and installed into every game as a tagged version.","image":{"src":"/logo.svg","alt":"Keel"},"actions":[{"theme":"brand","text":"Quick start","link":"/getting-started/create-a-game"},{"theme":"alt","text":"Build your first project","link":"/tutorials/first-project"},{"theme":"alt","text":"API Reference","link":"/api/"}]},"features":[{"title":"One boot, in order","details":"The Loader starts every Service and Controller in dependency order and the Scheduler runs their updates. One broken module logs an error instead of stopping the game.","link":"/guides/loader-and-scheduler"},{"title":"Validated networking","details":"Every message lives in one list. Net checks argument types, ranges and rate limits before any handler runs.","link":"/guides/networking"},{"title":"Server-authoritative state","details":"Player values are replicated to the right audience only, and the client watches them with State.Observe.","link":"/guides/state-and-replica"},{"title":"Saving that survives retries","details":"Session-locked player data with versioned migrations, plus Robux purchases that are granted exactly once.","link":"/guides/player-data"}]},"headers":[],"relativePath":"index.md","filePath":"index.md"}'),o={name:"index.md"};function i(n,e,d,l,h,c){return a(),r("div",null,[...e[0]||(e[0]=[s('<h2 id="what-keel-is" tabindex="-1">What Keel is <a class="header-anchor" href="#what-keel-is" aria-label="Permalink to &quot;What Keel is&quot;">​</a></h2><p>Keel is the framework behind my Roblox games. It is a set of Luau modules (Loader, Scheduler, Net, Defs, Entity, Data, State, Replica, a client UI layer, an admin Console and Purchases) plus a small starter game, a unit-test runner and a tool, <code>tools/keel.js</code>, that puts all of it into a game and updates it later.</p><p>It is built for <strong>Roblox Studio&#39;s Script Sync and GitHub only</strong>. There is no Rojo, no Wally and no package manager: Keel&#39;s files go to fixed places in your game and <code>keel.js</code> copies them there.</p><h2 id="why-it-exists" tabindex="-1">Why it exists <a class="header-anchor" href="#why-it-exists" aria-label="Permalink to &quot;Why it exists&quot;">​</a></h2><ul><li><strong>Bugs get fixed once.</strong> A game never edits Keel. A fix is made in the Keel repo, tagged, and installed into each game with <code>node tools/keel.js update &lt;tag&gt;</code>.</li><li><strong>A new game starts with the hard parts working.</strong> Loading, saving, networking, purchases and an admin console are already there.</li><li><strong>The server is the authority.</strong> The client sends what it wants to do; the server decides. Net validates every message before a handler sees it.</li><li><strong>Typos are caught early.</strong> Keel is <code>--!strict</code>, game data is checked against typed shapes at boot, and the Loader refuses dependency cycles and unknown names.</li></ul><h2 id="where-to-go-next" tabindex="-1">Where to go next <a class="header-anchor" href="#where-to-go-next" aria-label="Permalink to &quot;Where to go next&quot;">​</a></h2><table tabindex="0"><thead><tr><th>I want to...</th><th>Go to</th></tr></thead><tbody><tr><td>Start a game right now</td><td><a href="/Keel-Docs/getting-started/create-a-game">Create a game</a></td></tr><tr><td>Learn by building something</td><td><a href="/Keel-Docs/tutorials/first-project">Build your first project</a></td></tr><tr><td>Understand how the pieces fit</td><td><a href="/Keel-Docs/guides/architecture">Architecture</a></td></tr><tr><td>Look up a function</td><td><a href="/Keel-Docs/api/">API Reference</a></td></tr><tr><td>Find the Keel part that already does a job</td><td><a href="/Keel-Docs/reference/cheat-sheet">Cheat sheet</a></td></tr><tr><td>Fix something that is not working</td><td><a href="/Keel-Docs/reference/troubleshooting">Troubleshooting</a></td></tr></tbody></table><div class="info custom-block"><p class="custom-block-title">Note</p><p>The API pages are generated from the Keel source in this repository. The <a href="/Keel-Docs/changelog">Changelog</a> shows which version they describe and lists every release.</p></div>',8)])])}const p=t(o,[["render",i]]);export{u as __pageData,p as default};
